package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoPlaybackReviewTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun owner(a:HonorableVideoEditorActivity)=dialog().also{set(a,"inspectorReviewDialog",it);set(a,"captionReviewDialogs",linkedSetOf(it))}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,speed:Boolean,value:Float):Boolean{val p=get(a,"project")as VideoEditProject;return call(a,"commitPlaybackReview",d,r,p,0,p.segments[0],speed,value)as Boolean}
 @Test fun speedOnlyChangesPlaybackSpeedWithOneUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val music=p.soundtrack;val d=owner(a);val r=capture(a);assertTrue(commit(a,d,r,true,2f));assertEquals(before[0].copy(speed=2f),p.segments[0]);assertEquals(2500000L,p.segments[0].durationUs);assertEquals(before[0].captions,p.segments[0].captions);assertSame(music,p.soundtrack);assertNull(get(a,"inspectorReviewDialog"));assertTrue(p.undo());assertEquals(before,p.segments);assertFalse(p.canUndo);assertFalse(commit(a,d,r,true,.5f));assertTrue(p.canRedo)}
 @Test fun customVolumeOnlyChangesOriginalAudioAndRetainsMusic(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val music=p.soundtrack;val d=owner(a);assertTrue(commit(a,d,capture(a),false,.333f));assertEquals(before[0].copy(volume=.333f),p.segments[0]);assertSame(music,p.soundtrack);assertEquals(before[0].durationUs,p.segments[0].durationUs);assertTrue(p.undo());assertEquals(before,p.segments);assertFalse(p.canUndo)}
 @Test fun matchingSpeedAndCustomVolumeConsumeWithoutHistory(){for(speed in listOf(true,false)){val a=activity();val p=get(a,"project")as VideoEditProject;p.restore(p.segments.map{it.copy(volume=.333f)},soundtrack=p.soundtrack);val before=p.segments;val d=owner(a);assertTrue(commit(a,d,capture(a),speed,if(speed)1f else .333f));assertSame(before,p.segments);assertFalse(p.canUndo);assertNull(get(a,"inspectorReviewDialog"))}}
 @Test fun staleForegroundSourceDurationRangeGenerationSessionRecoveryBusyAndMusicRefuse(){for(flag in listOf("pause","source","duration","selection","generation","mode","recovery","busy","analysis","music")){val a=activity();val p=get(a,"project")as VideoEditProject;val d=owner(a);val r=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"selection"->set(a,"selectedClip",1);"generation"->set(a,"captionReviewGeneration",r.generation+1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"busy"->set(a,"saving",true);"analysis"->set(a,"analyzing",true);else->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f))};val before=p.segments;assertFalse(flag,commit(a,d,r,true,2f));assertSame(before,p.segments);assertNull(get(a,"inspectorReviewDialog"))}}
 @Test fun oldHiddenAndUntrackedPickersCannotMutateOrConsumeSuccessor(){for(flag in listOf("old","hidden","untracked")){val a=activity();val p=get(a,"project")as VideoEditProject;val old=owner(a);val r=capture(a);val next=if(flag=="old")owner(a)else null;when(flag){"hidden"->showing(old,false);"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>())};assertFalse(commit(a,old,r,false,.5f));assertFalse(p.canUndo);if(next!=null){assertSame(next,get(a,"inspectorReviewDialog"));assertTrue(commit(a,next,r,false,.5f))}}}
 @Test fun invalidValuesKeepOwnerForCorrectedModelInput(){for(speed in listOf(true,false)){val a=activity();val p=get(a,"project")as VideoEditProject;val d=owner(a);val r=capture(a);for(value in listOf(Float.NaN,Float.POSITIVE_INFINITY,-1f,3f)){try{commit(a,d,r,speed,value);fail("accepted invalid") }catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(d,get(a,"inspectorReviewDialog"));assertFalse(p.canUndo)};assertTrue(commit(a,d,r,speed,.5f));assertTrue(p.undo());assertFalse(p.canUndo)}}
 @Test fun customVolumeAndEverySupportedSpeedSurviveExistingCodec(){for(speed in listOf(.5f,1f,1.5f,2f)){val a=activity();val p=get(a,"project")as VideoEditProject;p.restore(p.segments.map{it.copy(speed=speed,volume=.333f)},soundtrack=p.soundtrack);val draft=VideoDraft(5000,p.segments,0,0,0,5000,soundtrack=p.soundtrack);assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertFalse(p.canUndo)}}
 @Test fun pausedBusyOrRecoveryEntriesReturnBeforePlaybackPickerWidgets(){for(speed in listOf(true,false))for(flag in listOf("pause","busy","recovery")){val a=activity();when(flag){"pause"->set(a,"workspaceActive",false);"busy"->set(a,"saving",true);else->set(a,"recoveryBytes",byteArrayOf(1))};call(a,"chooseClipPlayback",speed);assertNull(get(a,"inspectorReviewDialog"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
}
